import sys

def construct_permutation(N, K):
    if K > N:
        return -1
    permutation = list(range(1, N + 1))
    good_indices = permutation[:K]
    remaining = permutation[K:]
    remaining.reverse()
    for i in range(K):
        if good_indices[i] % (i + 1) != 0:
            good_indices[i], remaining[i] = remaining[i], good_indices[i]
    return good_indices + remaining if all(good_indices[i] % (i + 1) == 0 for i in range(K)) else -1

def main():
    T = int(sys.stdin.readline().strip())
    results = []
    for _ in range(T):
        N, K = map(int, sys.stdin.readline().strip().split())
        result = construct_permutation(N, K)
        if result == -1:
            results.append(result)
        else:
            results.append(' '.join(map(str, result)))
    print('\n'.join(results))

if __name__ == "__main__":
    main()
